// Option A: fused — avoid this outside demos.
class FusedTask extends Thread {
    @Override public void run() {
        System.out.println("running on " + Thread.currentThread().getName());
    }
}

// Option B: separated — prefer this always.
class SeparatedTask implements Runnable {
    private final String id;
    SeparatedTask(String id) { this.id = id; }
    @Override public void run() {
        System.out.println(id + " on " + Thread.currentThread().getName());
    }
}

