import java.util.concurrent.*;

public class RunnableOnPool {
    public static void main(String[] args) throws InterruptedException {
        // Same Runnable works on raw threads AND pools — that is the point.
        Runnable task = () -> {
            String name = Thread.currentThread().getName();
            System.out.println("task on " + name);
        };

        // Raw: one OS thread per task. Fine for 5, fatal for 5000.
        Thread raw = new Thread(task, "raw-1");
        raw.start();
        raw.join(); // caller waits; establishes happens-before

        // Pooled: bounded reuse. Prefer this in production.
        ExecutorService pool = Executors.newFixedThreadPool(4);
        try {
            for (int i = 0; i < 10; i++) pool.submit(task);
        } finally {
            pool.shutdown(); // user threads would otherwise pin the JVM open
            pool.awaitTermination(5, TimeUnit.SECONDS);
        }
    }
}
